#!/usr/bin/env python3

import argparse
import json
import pathlib
import subprocess
import sys
import time


# Rewrites include paths in MSVC compile commands to be valid in the workspace
# root instead of Bazel's execRoot.
def _patch_msvc_arguments(workspace_name, arguments):
    for i, arg in enumerate(arguments):
        # Example arguments generated by aquery in robinlinden/hastur:
        # * "/Iexternal/libpng+",
        # * "/external:Iexternal/libpng+",
        if arg.startswith("/Iexternal/"):
            arguments[i] = arg.replace(
                "/Iexternal/", f"/Ibazel-{workspace_name}/external/", 1
            )
        elif arg.startswith("/external:Iexternal/"):
            arguments[i] = arg.replace(
                "/external:Iexternal/",
                f"/external:Ibazel-{workspace_name}/external/",
                1,
            )


def _patch_linux_arguments(workspace_name, arguments):
    for i, arg in enumerate(arguments):
        if arg.startswith("external/"):
            arguments[i] = arg.replace(
                "external/", f"bazel-{workspace_name}/external/", 1
            )
        elif arg.startswith("--sysroot=external/"):
            arguments[i] = arg.replace(
                "--sysroot=external/", f"--sysroot=bazel-{workspace_name}/external/", 1
            )
        elif arg.startswith("-Bexternal/"):
            arguments[i] = arg.replace(
                "-Bexternal/", f"-Bbazel-{workspace_name}/external/", 1
            )


def _is_header_processing_action(arguments):
    return "-xc++-header" in arguments


def _action_to_compile_command(project_root, workspace_name, action):
    arguments = action.get("arguments", [])
    if not arguments:
        print(f"No arguments found for action: {action}", file=sys.stderr)
        return None

    # We currently can't find the relevant source_file for header-parsing
    # actions, so let's leave them out for now.
    if _is_header_processing_action(arguments):
        return None

    is_msvc = pathlib.Path(arguments[0]).name == "cl.exe"

    source_file = None

    if is_msvc:
        _patch_msvc_arguments(workspace_name, arguments)
    else:
        _patch_linux_arguments(workspace_name, arguments)

    for i, arg in enumerate(arguments):
        if arg in ("-c", "/c") and i + 1 < len(arguments):
            source_file = arguments[i + 1]
            break

    if source_file is None:
        print(
            f"No source file found for action with arguments: {arguments}",
            file=sys.stderr,
        )
        return None

    return {
        "directory": project_root,
        "arguments": arguments,
        "file": source_file,
    }


def _parse_args(argv):
    parser = argparse.ArgumentParser(
        description="Generate compile_commands.json from a Bazel workspace.",
        usage="%(prog)s [-h] [-- [aquery_args...]]",
    )
    parser.add_argument(
        "aquery_args",
        nargs=argparse.REMAINDER,
        help="arguments passed to bazel aquery",
    )

    args = parser.parse_args(argv)

    if args.aquery_args and argv[0] != "--":
        parser.error("aquery arguments must be preceded by '--'")

    if args.aquery_args and args.aquery_args[0] == "--":
        args.aquery_args = args.aquery_args[1:]

    return args


def main():
    args = _parse_args(sys.argv[1:])
    start_time = time.monotonic()

    project_root = subprocess.check_output(
        ["bazel", "info", "workspace"], text=True
    ).strip()

    workspace_name = project_root.rsplit("/")[-1]

    command = [
        "bazel",
        "aquery",
        # --include_param_files is broken on CppCompile actions, so we have to
        # disable the feature instead.
        # See: https://github.com/bazelbuild/bazel/issues/23293
        # "--include_param_files",
        "--features=-compiler_param_file",
        # layering_check adds a lot of '-fmodule-map-file'-arguments that aren't
        # useful for compile_commands.json.
        "--features=-layering_check",
        # Try to keep include-dirs pointing into the src-tree where possible.
        # See: https://github.com/bazelbuild/bazel/issues/17591
        "--features=skip_virtual_includes",
        # In my projects, tooling is included in the target configuration as
        # well, and including the same file twice doesn't make much sense.
        "--notool_deps",
        "--output=jsonproto",
        # Allow the user to pass additional arguments, e.g. if they want a
        # --config or whatever.
        *args.aquery_args,
        'mnemonic("CppCompile", deps(...))',
    ]

    print(f"Running '{' '.join(command)}'", file=sys.stderr)

    result = subprocess.run(
        command, stderr=None, stdout=subprocess.PIPE, text=True, check=True
    )

    aquery_output = json.loads(result.stdout)
    actions = aquery_output.get("actions", [])

    compile_commands = []

    print(f"Found {len(actions)} actions in aquery output", file=sys.stderr)
    for action in actions:
        compile_command = _action_to_compile_command(
            project_root, workspace_name, action
        )

        if compile_command is not None:
            compile_commands.append(compile_command)

    with open(f"{project_root}/compile_commands.json", mode="w", encoding="utf-8") as f:
        json.dump(compile_commands, f, indent=2)

    end_time = time.monotonic()
    print(
        f"Wrote {len(compile_commands)} compile commands to {project_root}/compile_commands.json after {end_time - start_time:.2f} seconds",
        file=sys.stderr,
    )


if __name__ == "__main__":
    main()
